## Takes a base directory from the command line.# All PDFs in that directory tree would be embedded# Output to ./chroma_db#import argparseimport pytesseract## The following line would need to be adjusted to point to the tesseract executable#pytesseract.pytesseract.tesseract_cmd = "/opt/homebrew/bin/tesseract"from openaicalls_cmd_v2 import make_llmfrom langchain_community.document_loaders import UnstructuredPDFLoaderfrom langchain.text_splitter import RecursiveCharacterTextSplitterfrom langchain.vectorstores import Chromafrom pathlib import Pathimport time# Function to process documents in batchesdef process_in_batches(batch_size, delay_time, filename):    global cnt    cnt = cnt + 1    print(f"\n===== {filename}")    loader = UnstructuredPDFLoader(filename)    docs = loader.load()    print("\nStart splitting")    text_splitter = RecursiveCharacterTextSplitter(        chunk_size=2000, chunk_overlap=400, add_start_index=True    )    print("\nCompiling splits")    all_splits = text_splitter.split_documents(docs)    print("\nStart embedding")    for i in range(0, len(all_splits), batch_size):        batch = all_splits[i:i + batch_size]        ids = [str(cnt) + "_" + str(j) for j in range(i, i + batch_size)]        try:            print("\n" + str(ids) + "\n")            Chroma.from_documents(batch, emb, ids=ids, persist_directory="./chroma_db")        except Exception as error:            print(f"Handling request: {error}")            exit()        time.sleep(delay_time)  # Pause between batchesif __name__ == '__main__':    # Parse command-line arguments    parser = argparse.ArgumentParser(description="Process PDFs from a specified base directory.")    parser.add_argument('base_dir', type=str, help='Base directory to search for PDF files')    args = parser.parse_args()    base_dir = Path(args.base_dir)    model, emb = make_llm()    cnt = 0    # Set the batch size and delay time    batch_size = 10  # Adjust this based on your rate limit    delay_time = 2   # Adjust the delay time in seconds    # Main Program: Process all PDF files in the given base_dir    for pdf_file in base_dir.rglob('*.pdf'):         process_in_batches(batch_size, delay_time, str(pdf_file))    print("Done.")